# 12 — L, quantum.  Photon momentum.
# ═════════════════════════════════════════════════════════════════════════════
{
    "n": 12, "id": "S05-12", "module": "L", "diff": 2,
    "topic": "The momentum of a photon of given wavelength",
    "rel": [("L", "A photon's momentum is h divided by its wavelength"),
            ("L", "Converting the wavelength to metres before using h = 6.6 x 10^-34 J s"),
            ("A", "Checking the dimensions: (J s) / m = kg m/s")],
    "key": ["photon", "momentum", "hlambda"],
    "stem": '<p>What is the momentum of a photon of wavelength 600 nm? (Use h = 6.6 x 10^-34 J s.)</p>',
    "opts": ['3.3 x 10^-19 kg m s^-1', '5.5 x 10^-28 kg m s^-1', '1.1 x 10^-19 kg m s^-1', '1.1 x 10^-27 kg m s^-1', '6.6 x 10^-34 kg m s^-1'],
    "ans": 3,
    "distractors": ['computes the photon energy h c / lambda and forgets to divide by c, giving a momentum-sized number of wrong dimensions', 'drops a factor of ten in the wavelength conversion from nanometres', 'uses the photon energy h f without dividing by c, so the value is too large by a factor of c', 'correct', "returns Planck's constant itself, having ignored the wavelength entirely"],
    "profile": {
        "steps": [
            ("relate", "photon momentum is p = h / lambda"),
            ("relate", "600 nm = 600 x 10^-9 m = 6.0 x 10^-7 m"),
            ("eliminate", "substitute h = 6.6 x 10^-34 J s and lambda = 6.0 x 10^-7 m"),
            ("solve", "p = 6.6 x 10^-34 / (6.0 x 10^-7) = 1.1 x 10^-27 kg m s^-1"),
            ("check", "the dimensions are (J s)/m = (kg m^2 s^-2 s)/m = kg m/s, a momentum, which is right"),
        ],
        "relations": ["p = h / lambda", "lambda = 600 x 10^-9 m", "p = 6.6e-34 / 6.0e-7"],
        "insight": "A photon carries momentum h/lambda, not energy. Energy is hc/lambda; divide by c (or use p = E/c) to get the momentum, and do not confuse the two. The wavelength must be in metres, so 600 nm is 6.0 x 10^-7 m.",
        "shape": "units-consistency",
        "approx": False,
        "symbolic": False,
        "figure_essential": False,
    },
    "check": {"kind": "eval", "expr": "6.6e-34/600e-9", "want": "1.1e-27"},
    "sol": '<p><b>What is being tested.</b> The photon momentum formula <code>p = h/lambda</code>, and keeping it distinct from the photon energy <code>E = hc/lambda</code>.</p>\n<p><b>Step 1 — the formula.</b> A photon of wavelength lambda has momentum</p>\n<div class="formula">p = h / lambda</div>\n<p><b>Step 2 — the wavelength in metres.</b></p>\n<div class="formula">600 nm = 600 x 10^-9 m = 6.0 x 10^-7 m</div>\n<p><b>Step 3 — substitute.</b></p>\n<div class="formula">p = 6.6 x 10^-34 / (6.0 x 10^-7) = 1.1 x 10^-27 kg m s^-1</div>\n<p>So <b>Answer: D.</b></p>\n<p><b>Step 4 — dimensional check.</b> <code>(J s)/m = (kg m^2 s^-2 s)/m = kg m/s</code>, which is a momentum. That confirms the formula, not the energy.</p>\n<p><b>The distractors.</b></p>\n<p>&middot; <b>3.3 x 10^-19</b> is the photon energy <code>hc/lambda</code>, the wrong quantity.</p>\n<p>&middot; <b>5.5 x 10^-28</b> loses a factor of ten in the nanometre-to-metre conversion.</p>\n<p>&middot; <b>1.1 x 10^-19</b> uses the energy <code>hf</code> without dividing by <code>c</code>, massively too large.</p>\n<p>&middot; <b>6.6 x 10^-34</b> is just Planck\'s constant with the wavelength ignored.</p>\n<p><b>Relevant topics:</b> photon momentum; p = h/lambda; the difference between photon energy and momentum.</p>',
    "trap": "Computing the photon energy hc/lambda and offering it as the momentum, or forgetting to convert 600 nm to 6.0 x 10^-7 m. Momentum is h/lambda, not hc/lambda.",
},

